const walker = require('@cloudflare/json-schema-walker');
const mergeCfRecurse = require('./mergeCfRecurse');
const collapser = require('./allOf');
const example = require('./example');

/**
 * Process a dereferenced (no "$ref") hyper-schema into a form most suitable
 * for rendering API documentation.  This involves:
 *  - De-referencing the Doca extension keyword "cfRecurse"
 *  - Collapsing "allOf", on the assumption that it is used as glue rather
 *    then to indicate structure that programmers should care about.
 *  - Rolling up "example" fields so that object and array schemas that
 *    do not define their own example, but which have examples defined
 *    for all properties or items, gain an example built from those
 *    property and item examples.
 *  - Generating a curl request (with syntax typical of curl on *NIX)
 *    for each endpoint that uses the rolled up examples.
 *  - draft-04 hyper-schema is assumed if there is no "$schema" keyword.
 *
 * The currently supported options in the second parameter are:
 *  - baseUri:
 *      An absolute URI against which the link hrefs will be resolved
 *      to produce example requests.  In general, this should end
 *      in a "/" while the link hrefs should *NOT* begin with a "/",
 *      in order for RFC 3986 URI reference resolution to be functionally
 *      equivalent to string concatenation.  Otherwise many people find
 *      the results to be counter-intuitive.
 *  - globalHeaderSchema:
 *      A schema for headers that, by default, should always be sent
 *      with every request.  The header schemas should have "example"
 *      fields that are used to generate example requests.  These
 *      defaults can be overridden (not extended) for each link
 *      with the "headerSchema" keyword.
 *
 * Notable limitations aside from not allowing references include:
 *  - Some "allOf" combinations cannot be collapsed, and we currently
 *    do not support leaving such combinations present as "allOf"s.
 *  - It is possible in complex schemas to end up with an example
 *    that is not valid against the processed schema.  For instance,
 *    if an example of "Hello, world!" comes from an "allOf" subschema
 *    that just defines a type of string, but another subschema in the
 *    allOf sets a maxLength of 5, "Hello, world!" is longer than five
 *    characters and is now an invalid example.  Currently, such situations
 *    are not automatically detected.
 *  - Currently, Cloudflare's Doca extensions are always assumed to be
 *    in use.  This is only a limitation if identically named keywords
 *    are being used with a different intended behavior.  Doca keywords
 *    are prefixed with "cf" to make this unlikely.
 *  - In the absence of $schema, we assume JSON Hyper-Schema draft-04.
 */
function processApiDocSchema(schema, options) {
  let walkerVocab = Object.assign(
    {},
    walker.getVocabulary(schema, walker.vocabularies.DRAFT_04_HYPER),
    walker.vocabularies.CLOUDFLARE_DOCA
  );

  mergeCfRecurse.mergeCfRecurse(schema, walkerVocab);

  let collapseCallback = collapser.getCollapseAllOfCallback(
    schema.$schema || 'http://json-schema.org/draft-04/hyper-schema#',
    collapser.vocabularies.CLOUDFLARE_DOCA
  );

  // TODO: In theory, these two could be combined into one walk,
  //       as they both only work with subschemas, but in practice
  //       that does not work.  Need to investigate.
  walker.schemaWalk(
    schema,
    null,
    (...args) => {
      collapseCallback(...args);
    },
    walkerVocab
  );
  walker.schemaWalk(
    schema,
    null,
    (...args) => {
      example.rollUpExamples(...args);
    },
    walkerVocab
  );

  // Curl examples need to be run through the walker
  // separately, because they need the root schema
  // to be fully processed by the previous steps,
  // and the walker visits it last.
  let curlCallback = example.getCurlExampleCallback(
    schema,
    (options && options.baseUri) || '',
    (options && options.globalHeaderSchema) || {}
  );
  walker.schemaWalk(schema, null, curlCallback, walkerVocab);
  return schema;
}

module.exports = {
  processApiDocSchema
};

const loaderUtils = require('loader-utils');
const validateOptions = require('schema-utils');
const transform = require('@cloudflare/json-schema-transform');

module.exports = function(source) {
  this.cacheable && this.cacheable();

  const optionsSchema = {
    type: 'object',
    properties: {
      baseUri: {
        type: 'string',
        format: 'uri',
        description:
          'The URI used as the base for resolving example URIs from link hrefs'
      },
      globalHeaderSchema: {
        type: 'object',
        description:
          'JSON Schemas for HTTP request headers to use with examples unless overridden by cfRequestHeaders'
      }
    }
  };

  const options = loaderUtils.getOptions(this);
  options &&
    validateOptions(optionsSchema, options, 'API Documentation Loader');

  let schema = eval(source);
  transform.processApiDocSchema(schema, options);
  this.value = [schema];
  return `module.exports = ${JSON.stringify(schema, null, 2)};`;
};

const fs = require('fs');
const path = require('path');
const transform = require('../index.js');

describe('Dereferencer system test', () => {
  beforeAll(() => {
    this.fixtureDir = path.join(__dirname, 'fixtures');
    this.refDir = path.join(this.fixtureDir, 'refs');
    this.schemaLocalPath = path.join(this.fixtureDir, 'refs.json');
    this.schemaUri = 'file://' + this.schemaLocalPath;

    this.expectedSchema = JSON.parse(
      fs.readFileSync(path.join(this.fixtureDir, 'refs-resolved.json'))
    );

    // Now set up the expected dependencies data.
    this.expectedDependencies = [
      'json',
      'yaml',
      'json5',
      'js',
      'noext',
      'withext.json'
    ].map(e => {
      let suffix = e === 'noext' || e === 'withext.json' ? '' : `.${e}`;

      return {
        uri: 'file://' + `${this.refDir}/${e}`,
        localPath: `${this.refDir}/${e}${suffix}`
      };
    });

    // The initial file itself is also included
    this.expectedDependencies.push({
      uri: this.schemaUri,
      localPath: this.schemaLocalPath
    });

    // Comparison function for sorting dependency arrays
    this.dependenciesCmp = (a, b) => {
      if (a.uri < b.uri) {
        return -1;
      } else if (a.uri > b.uri) {
        return 1;
      }
      return 0;
    };
    this.expectedDependencies.sort(this.dependenciesCmp);
  });

  test('Dereference by schema URI', async () => {
    let aed = new transform.AutoExtensionDereferencer(this.schemaUri);
    let dereferenced = await aed.dereference();

    expect(dereferenced).toEqual(this.expectedSchema);

    // While not currently public, check that we save the parsed object.
    expect(dereferenced).toEqual(aed._schemaData);

    let dependencies = aed.getDependencies();
    dependencies.sort(this.dependenciesCmp);

    expect(dependencies).toEqual(this.expectedDependencies);
  });

  test('Dereference with parsed data', async () => {
    let parsedSchema = JSON.parse(
      fs.readFileSync(path.join(this.fixtureDir, 'refs.json'))
    );

    // Give it a path that doesn't exist, as the underlying code
    // should ignore it in favor of the parsed data, and just
    // use it for resolving relative references. So just switch
    // it to .yaml which is not present on the filesystem.
    let aed = new transform.AutoExtensionDereferencer(
      this.schemaUri.replace(/json$/, 'yaml'),
      parsedSchema
    );
    let dereferenced = await aed.dereference();

    expect(dereferenced).toEqual(this.expectedSchema);
    expect(dereferenced).toEqual(aed._schemaData);
  });

  test('Require file:// URI', () => {
    expect(() => {
      new transform.AutoExtensionDereferencer(this.schemaLocalPath);
    }).toThrow();
  });

  test('No relevant file causes exception', async () => {
    let aed = new transform.AutoExtensionDereferencer(
      'file://' + path.join(this.fixtureDir, 'refs-dangling.json')
    );
    try {
      await aed.dereference();
    } catch (e) {
      expect(e.code).toEqual('ENOENT');
    }
  });
});

'use strict';

var ldoLib = require('../lib/ldo');

describe('Extract one or more LDOs from a hyper-schema', () => {
  beforeEach(() => {
    this.schema = {
      links: [
        {
          // Omit method to test defaulting to GET.
          title: 'List the Things',
          rel: 'collection',
          href: 'things'
        },
        {
          title: 'Create a Thing',
          rel: 'collection',
          href: 'things',
          method: 'POST'
        },
        {
          title: 'Fetch a Thing',
          rel: 'self',
          href: 'things/{id}',
          method: 'GET'
        },
        {
          title: 'Delete a Thing',
          rel: 'self',
          href: 'things/{id}',
          method: 'DELETE'
        }
      ]
    };
  });

  test('Extract multiple; extract by rel', () => {
    let ldos = ldoLib.extractLdos({ rel: 'self' }, this.schema);
    expect(ldos[0]).toBe(this.schema.links[2]);
    expect(ldos[1]).toBe(this.schema.links[3]);
    expect(ldos.length).toBe(2);
  });

  test('Extract single; extract by title', () => {
    let ldo = ldoLib.extractLdo({ title: 'list the things' }, this.schema);
    expect(ldo).toBe(this.schema.links[0]);
  });

  test('Multiple values error; extract by method', () => {
    expect(
      ldoLib.extractLdo.bind(null, { method: 'GET' }, this.schema)
    ).toThrow('Found duplicate links for \'{"method":"GET"}\'');
  });

  test('No values empty list; ignore other fields', () => {
    expect(ldoLib.extractLdos({ href: 'things' }, this.schema)).toEqual([]);
  });

  test('No values error', () => {
    expect(
      ldoLib.extractLdo.bind(null, { method: 'PATCH' }, this.schema)
    ).toThrow('No link found for \'{"method":"PATCH"}\'');
  });
});

describe('Resolve URI Templates', () => {
  beforeAll(() => {
    // Note that "zone.id" should never be used, only the nested zone id.
    this.data = {
      id: 1,
      zone: { id: 2 },
      'zone.id': 3
    };
    this.input = {
      zone: { id: 4 }
    };
  });

  test('Nested namespace, mixed styles', () => {
    expect(
      ldoLib.resolveUri(
        { href: 'nonsense/{zone.id}/whatever/{id}' },
        this.data,
        this.input
      )
    ).toEqual('nonsense/4/whatever/1');
  });

  test('No data provided', () => {
    // Unfilled template variables are removed per RFC.
    expect(ldoLib.resolveUri({ href: 'foo{?bar}' })).toEqual('foo');
  });

  test('Insufficient data provided', () => {
    // Unfilled template variables are removed per RFC.
    expect(ldoLib.resolveUri({ href: 'foo{?a.b.c}' }, { d: 1 })).toEqual('foo');
  });

  test('No href provided', () => {
    expect(ldoLib.resolveUri.bind(null, { rel: 'item' }, {})).toThrow(
      'No href to resolve!'
    );
  });
});

const yaml = require('node-yaml');
const walker = require('@cloudflare/json-schema-walker');
const transform = require('../index.js');

describe('System Tests', () => {
  test('mergeCfRecurse', () => {
    let schema = yaml.readSync(__dirname + '/fixtures/system.yaml');
    let expected = yaml.readSync(
      __dirname + '/fixtures/system-no-cfrecurse.yaml'
    );
    transform.mergeCfRecurse(schema);
    expect(schema).toEqual(expected);
  });

  test('collapseAllOf', () => {
    let schema = yaml.readSync(
      __dirname + '/fixtures/system-no-cfrecurse.yaml'
    );
    let expected = yaml.readSync(__dirname + '/fixtures/system-no-allof.yaml');
    let cb = transform.getCollapseAllOfCallback(
      schema.$schema,
      transform.vocabularies.CLOUDFLARE_DOCA
    );
    walker.schemaWalk(schema, null, cb, walker.vocabularies.CLOUDFLARE_DOCA);
    expect(schema).toEqual(expected);
  });

  test('rollupExamples', () => {
    let schema = yaml.readSync(__dirname + '/fixtures/system-no-allof.yaml');
    let expected = yaml.readSync(__dirname + '/fixtures/system-examples.yaml');

    walker.schemaWalk(
      schema,
      null,
      transform.rollUpExamples,
      walker.vocabularies.CLOUDFLARE_DOCA
    );
    expect(schema).toEqual(expected);
  });

  test('curlExample', () => {
    let schema = yaml.readSync(__dirname + '/fixtures/system-examples.yaml');
    let expected = yaml.readSync(__dirname + '/fixtures/system-curl.yaml');

    let cb = transform.getCurlExampleCallback(
      schema,
      'https://example.com/api/',
      {
        example: {
          Accept: 'application/json',
          'Content-Type': 'application/json'
        }
      }
    );
    walker.schemaWalk(schema, null, cb, walker.vocabularies.CLOUDFLARE_DOCA);
    expect(schema).toEqual(expected);
  });

  test('apiDoc', () => {
    // This test should be equivalent to doing all of the above in sequence

    let schema = yaml.readSync(__dirname + '/fixtures/system.yaml');
    let expected = yaml.readSync(__dirname + '/fixtures/system-curl.yaml');

    transform.processApiDocSchema(schema, {
      baseUri: 'https://example.com/api/',
      globalHeaderSchema: {
        example: {
          Accept: 'application/json',
          'Content-Type': 'application/json'
        }
      }
    });
    expect(schema).toEqual(expected);
  });

  test('apiDoc with defaults', () => {
    let schema = yaml.readSync(__dirname + '/fixtures/system.yaml');
    let expected = yaml.readSync(
      __dirname + '/fixtures/system-curl-defaults.yaml'
    );

    // Ensure that we use the default meta-schema
    delete schema.$schema;

    // Test overridding the default lack of headers
    schema.links[schema.links.length - 1].headerSchema = {
      example: {
        accept: 'application/json, application/problem+json'
      }
    };

    transform.processApiDocSchema(schema);
    expect(schema).toEqual(expected);
  });
});
